actions.action:
f_aktivna: f.f_aktivna, f_pocet: f.f_pocet, f_ludia: f.f_ludia, f_historia: f.f_historia;

change f_aktivna value { true }
change f_pocet value { 0 }
change f_ludia value { "(nobody yet)" }
change f_historia value { "" }
changeCaseProperty("title").about { ((useCase.visualId ?: "New company") as String) }

document.function:
{ ->
    // Identifikator nesie URI cestu, takze sesterska siet sa odvodzuje
    // z vlastneho identifikatora - premenovanie uzla sa prejavi na jednom mieste.
    def pid = useCase.processIdentifier as String
    def prefix = pid.contains("/") ? pid.substring(0, pid.lastIndexOf("/") + 1) : ""
    return prefix + "sd_ticket"
}

{ def hodnota ->
    def mail = ((hodnota ?: "") as String).trim()
    return mail ==~ /^[^@\s]+@[^@\s.]+\.[^@\s]{2,}$/
}

{ def userId ->
    // Firma, v ktorej clovek uz je - okrem tejto. `findCases { it.dataSet... }`
    // nefunguje, takze sa filtruje v Groovy.
    def id = (userId ?: "") as String
    if (!id) return null
    return findCases { it.processIdentifier.eq(useCase.processIdentifier) }.find { c ->
        c.stringId != useCase.stringId && userIdsOf(c.dataSet["f_clenovia"]?.value).contains(id)
    }
}

{ def userId ->
    def s = userSnapshot(userId as String)
    if (!s) return "(deleted account " + userId + ")"
    def meno = (((s.meno ?: "") + " " + (s.priezvisko ?: "")) as String).trim()
    // Pozvany ucet ma meno "unknown", kym si ho clovek nevyplni.
    if (!meno || meno == "unknown unknown") meno = ""
    def stav = (s.stav as String) == "ACTIVE" ? "active" : ((s.stav as String) == "INVITED" ? "invited" : ((s.stav ?: "?") as String).toLowerCase())
    return (meno ? meno + " <" + s.email + ">" : (s.email as String)) + " - " + stav
}

{ def ids, def f_ludia, def f_pocet, def f_odobrat ->
    // Citatelny zoznam a moznosti pola na odobratie. Moznosti sa nastavuju
    // TU, kde sa zapisuje hodnota - v `create` udalosti by sa neuchovali (B20).
    def opts = [:]
    def riadky = []
    (ids ?: []).each { id ->
        def p = popis_cloveka(id)
        riadky << ("• " + p)
        opts[id as String] = p
    }
    change f_ludia value { riadky ? riadky.join("\n") : "(nobody yet)" }
    change f_pocet value { (ids ?: []).size() }
    change f_odobrat options { opts }
    change f_odobrat value { null }
}

{ def ids, def nazov ->
    // Ludia firmy a jej nazov do tiketov, ktore uz existuju. Rozpisane tikety
    // sa preskakuju: vidi ich len autor a `t_detail`, cez ktory sa zapisuje,
    // vznikne az podanim.
    def firmaId = useCase.stringId
    int ok = 0
    int chyby = 0
    findCases { it.processIdentifier.eq(siet_tiketu()) }.each { t ->
        if (((t.getFieldValue("tk_firma_id") ?: "") as String) != firmaId) return
        if (((t.getFieldValue("tk_stav") ?: "") as String) == "rozpisana") return
        try {
            setData("t_detail", t, [
                    "tk_firma_nazov": ["value": (nazov ?: "") as String, "type": "text"],
                    "tk_firma_ludia": ["value": (ids ?: []).collect { it as String }, "type": "userList"],
            ])
            ok++
        } catch (Exception e) {
            chyby++
        }
    }
    return [ok: ok, chyby: chyby]
}

{ ->
    def u = loggedUser()
    if (u == null) return "(unknown)"
    return (u.hasProperty("email") && u.email) ? (u.email as String) : (u.stringId as String)
}

{ def f_historia, def riadok ->
    // Novsie navrch, so stropom - pole je v dataSet a cita sa pri kazdom
    // otvoreni formulara.
    def ked = java.time.LocalDateTime.now().format(
            java.time.format.DateTimeFormatter.ofPattern("dd.MM.yyyy HH:mm"))
    def stare = ((f_historia.value ?: "") as String).split("\n").findAll { it.trim() }
    return ([ked + " · " + riadok + " · " + kto()] + (stare as List)).take(200).join("\n")
}

actions.action:
f_nazov: f.f_nazov;

def n = ((f_nazov.value ?: "") as String).trim()
if (n) {
    changeCaseProperty("title").about { n }
}

f_clenovia: f.f_clenovia, f_ludia: f.f_ludia, f_pocet: f.f_pocet, f_odobrat: f.f_odobrat,
f_vysledok: f.f_vysledok, f_nazov: f.f_nazov;

// Stav uctov sa meni mimo tejto siete (clovek si z mailu nastavi heslo),
// a rola na novej verzii sd_ticket po re-importe chyba. Oboje sa tu dorovna.
def ids = userIdsOf(f_clenovia.value)
def roly = 0
ids.each { id ->
    if (setProcessRole(id as String, "zakaznik", siet_tiketu(), "", true)) roly++
}
obnov_zoznam(ids, f_ludia, f_pocet, f_odobrat)
def r = prepocitaj_tikety(ids, (f_nazov.value ?: "") as String)
change f_vysledok value {
    "Refreshed: " + ids.size() + " people, customer role confirmed for " + roly +
    ", requests updated: " + r.ok + (r.chyby ? (", FAILED: " + r.chyby) : "")
}

f_novy_email: f.f_novy_email, f_clenovia: f.f_clenovia, f_ludia: f.f_ludia,
f_pocet: f.f_pocet, f_odobrat: f.f_odobrat, f_vysledok: f.f_vysledok,
f_historia: f.f_historia, f_nazov: f.f_nazov;

// Odmietnutie sa NEHADZE: z datoveho tlacidla by skoncilo ako chyba
// requestu, nie ako veta vo formulari, a clovek by nevedel, co opravit.
def mail = ((f_novy_email.value ?: "") as String).trim()
if (!je_email(mail)) {
    change f_vysledok value { "\"" + mail + "\" is not a valid e-mail address." }
    return
}
if (!((f_nazov.value ?: "") as String).trim()) {
    change f_vysledok value { "Fill in the company name first." }
    return
}
def ids = userIdsOf(f_clenovia.value)
def ucet = findUserByEmail(mail)
if (ucet != null) {
    def uid = ucet.stringId as String
    if (ids.contains(uid)) {
        change f_vysledok value { mail + " is already at this company." }
        return
    }
    def ina = firma_cloveka(uid)
    if (ina != null) {
        change f_vysledok value {
            mail + " is already at the company \"" + ((ina.dataSet["f_nazov"]?.value ?: ina.title) as String) +
            "\". A person can belong to one company only - remove them there first."
        }
        return
    }
    if (hasProcessRole(ucet, "podpora", siet_tiketu())) {
        change f_vysledok value { mail + " is support staff and cannot be a customer." }
        return
    }
}

// Aktivny ucet pozvanku nedostane - uz sa vie prihlasit, staci mu pristup.
def riadky = []
def uid
if (ucet != null && (ucet.state as String) == "ACTIVE") {
    uid = ucet.stringId as String
    riadky << (mail + " already has an account - access granted, no invitation sent")
} else {
    def v = pozvi(mail)
    if (!v.ok) {
        change f_vysledok value { "NOT ADDED: " + (v.sprava as String) }
        change f_historia value { do_historie(f_historia, mail + " - NOT ADDED: " + (v.sprava as String)) }
        return
    }
    uid = v.userId as String
    riadky << (v.sprava as String)
}

if (!setProcessRole(uid, "zakaznik", siet_tiketu(), "", true)) {
    riadky << "WARNING: the customer role could not be assigned - is sd_ticket imported?"
}
ids = ids + [uid]
change f_clenovia value { ids }
obnov_zoznam(ids, f_ludia, f_pocet, f_odobrat)
def r = prepocitaj_tikety(ids, (f_nazov.value ?: "") as String)
if (r.ok || r.chyby) {
    riadky << ("requests of the company updated: " + r.ok + (r.chyby ? (", FAILED: " + r.chyby) : ""))
}
change f_novy_email value { "" }
change f_vysledok value { riadky.join("\n") }
change f_historia value { do_historie(f_historia, mail + " added") }

f_odobrat: f.f_odobrat, f_clenovia: f.f_clenovia, f_ludia: f.f_ludia,
f_pocet: f.f_pocet, f_vysledok: f.f_vysledok, f_historia: f.f_historia, f_nazov: f.f_nazov;

def uid = ((f_odobrat.value ?: "") as String).trim()
def ids = userIdsOf(f_clenovia.value)
if (!uid || !ids.contains(uid)) {
    change f_vysledok value { "Pick the person to remove first." }
    return
}
def popis = popis_cloveka(uid)
ids = ids.findAll { it != uid }
change f_clenovia value { ids }
// Clovek patri do jednej firmy, takze bez nej rolu zakaznika nepotrebuje.
// Enginove `removeRole` sa nepouziva - v 6.3.1 mlcky nic neodoberie.
setProcessRole(uid, "zakaznik", siet_tiketu(), "", false)
obnov_zoznam(ids, f_ludia, f_pocet, f_odobrat)
def r = prepocitaj_tikety(ids, (f_nazov.value ?: "") as String)
change f_vysledok value {
    "Removed: " + popis + "\nrequests of the company updated: " + r.ok +
    (r.chyby ? (", FAILED: " + r.chyby) : "")
}
change f_historia value { do_historie(f_historia, popis + " removed") }

f_nazov: f.f_nazov;

if (!((f_nazov.value ?: "") as String).trim()) {
    throw new java.lang.IllegalStateException("Fill in the company name.")
}
